// ─── File: src/test/java/com/bank/cow/CopyOnWriteTest.java ───
package com.bank.cow;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class CopyOnWriteTest {

    // ═══ Iterator = snapshot, never CME ═══
    @Test
    void iterator_snapshot_neverCME() {
        CopyOnWriteArrayList<String> list = new CopyOnWriteArrayList<>(
            List.of("SAV2001", "CUR3001"));

        Iterator<String> it = list.iterator();  // snapshot!
        list.add("FD4001");  // modify AFTER iterator created

        // Iterator sees OLD snapshot — no CME!
        List<String> iterated = new ArrayList<>();
        it.forEachRemaining(iterated::add);
        assertThat(iterated).containsExactly("SAV2001", "CUR3001");  // FD4001 NOT seen!
        assertThat(list).hasSize(3);  // actual list has 3
    }

    // ═══ ArrayList iterator WOULD throw CME ═══
    @Test
    void arrayList_throwsCME() {
        ArrayList<String> list = new ArrayList<>(List.of("A", "B"));
        assertThatThrownBy(() -> {
            for (String s : list) {
                list.add("C");  // modify during iteration → CME!
            }
        }).isInstanceOf(ConcurrentModificationException.class);
    }

    // ═══ Thread-safe concurrent reads + writes ═══
    @Test
    void threadSafe_concurrentAccess() throws InterruptedException {
        CopyOnWriteArrayList<String> list = new CopyOnWriteArrayList<>();
        list.add("INITIAL");

        ExecutorService pool = Executors.newFixedThreadPool(4);
        CountDownLatch latch = new CountDownLatch(4);

        // 2 writers:
        for (int w = 0; w < 2; w++) {
            final int id = w;
            pool.submit(() -> {
                for (int i = 0; i < 100; i++) list.add("W" + id + "-" + i);
                latch.countDown();
            });
        }

        // 2 readers (concurrent):
        for (int r = 0; r < 2; r++) {
            pool.submit(() -> {
                for (int i = 0; i < 1000; i++) {
                    for (String s : list) { /* read snapshot — no CME! */ }
                }
                latch.countDown();
            });
        }

        latch.await(10, TimeUnit.SECONDS);
        pool.shutdown();
        assertThat(list).hasSize(1 + 200);  // INITIAL + 200 writes
    }
}
