class EventBus {
    // snapshot-based: every mutation copies the backing array
    private final List<TradeListener> listeners =
        new CopyOnWriteArrayList<>();

    void register(TradeListener l){ listeners.add(l); }   // O(n) copy
    void unregister(TradeListener l){ listeners.remove(l);} // O(n) copy

    void publish(TradeEvent e) {
        // iterates a stable snapshot — no CME even if list mutates
        for (TradeListener l : listeners)      // lock-free read
            l.onTrade(e);                      // 50K calls/sec, 0 contention
    }
    // Internally: volatile Object[] array; writers lock + Arrays.copyOf,
    // readers see immutable snapshot ⇒ never ConcurrentModification.
    // ❌ Avoid when writes are frequent (copy cost dominates).
}
